// Herringbone parquet, as geometry rather than as drawing.
//
// The planks are returned as polygons so the same function can be rasterised
// outside a browser and looked at. A canvas painter that only exists inside
// the scene is a thing you cannot check: the floor is seen at a grazing angle
// in a dark room, which is exactly where a wrong pattern hides.
//
// Two planks — one lying along x, one along y — sit at every point of the
// lattice generated by s = (L+W, W-L) and t = (W, W). That lattice has
// determinant 2LW, which is the area of exactly those two planks, so the
// planks meet edge to edge and leave nothing over.

/**
 * Plank polygons covering `width` x `height`, laid at `angle` to the axes.
 * Each is { points: [[x,y] x4], along: 'x' | 'y', index } — `index` is stable
 * per plank so a painter can shade each one consistently.
 */
export function herringbone({ width, height, plankW, plankL, angle = Math.PI / 4 }) {
  const cos = Math.cos(angle)
  const sin = Math.sin(angle)
  const cx = width / 2
  const cy = height / 2

  // Rotating about the middle means the pattern has to be generated over the
  // diagonal, or the corners come up bare.
  const reach = Math.hypot(width, height) / 2 + plankL * 2

  const rect = (x, y, w, h) => [[x, y], [x + w, y], [x + w, y + h], [x, y + h]]
    .map(([px, py]) => {
      const dx = px
      const dy = py
      return [cx + dx * cos - dy * sin, cy + dx * sin + dy * cos]
    })

  const s = [plankL + plankW, plankW - plankL]
  const t = [plankW, plankW]

  // Enough lattice steps in each direction to cover the reach in every
  // direction; the lattice vectors are short next to it, so this is generous
  // rather than tight.
  const na = Math.ceil(reach / Math.min(Math.abs(s[0]), Math.abs(s[1]))) + 2
  const nb = Math.ceil((reach * 2) / plankW) + 2

  const planks = []
  let index = 0
  for (let a = -na; a <= na; a++) {
    for (let b = -nb; b <= nb; b++) {
      const bx = a * s[0] + b * t[0]
      const by = a * s[1] + b * t[1]
      if (Math.hypot(bx, by) > reach + plankL * 2) continue
      planks.push({ points: rect(bx, by, plankL, plankW), along: 'x', index: index++ })
      planks.push({ points: rect(bx + plankL, by + plankW - plankL, plankW, plankL), along: 'y', index: index++ })
    }
  }
  return planks
}
